{
  "ingredients": [
    {
      "name": "potatoes",
      "quantity": "4 medium"
    },
    {
      "name": "onion",
      "quantity": "1"
    },
    {
      "name": "olive oil",
      "quantity": "plenty"
    },
    {
      "name": "eggs",
      "quantity": "6"
    },
    {
      "name": "salt",
      "quantity": "to taste"
    }
  ],
  "steps": [
    "Peel and slice the potatoes thinly.",
    "Chop the onion.",
    "Fry the potatoes and onion in plenty of olive oil for 15 minutes over medium heat.",
    "Beat the eggs in a large bowl with salt.",
    "Mix the potatoes and onion with the eggs and let stand for 5 minutes.",
    "Pour the mixture into a hot pan with a little oil.",
    "Cook for 4 minutes per side."
  ]
}
